import express from "express";
import path from "path";
import { GoogleGenAI, Type } from "@google/genai";
import dotenv from "dotenv";

dotenv.config();

const app = express();
const PORT = 3000;

app.use(express.json());

// Initialize Gemini SDK with telemetry header
const getGeminiClient = () => {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    console.warn("WARNING: GEMINI_API_KEY is not defined. AI course generation will fail.");
  }
  return new GoogleGenAI({
    apiKey: apiKey || "MOCK_KEY_FOR_BUILD",
    httpOptions: {
      headers: {
        'User-Agent': 'aistudio-build',
      }
    }
  });
};

// Course generation endpoint
app.post("/api/courses/generate", async (req, res) => {
  const { topic } = req.body;
  if (!topic || typeof topic !== "string" || topic.trim() === "") {
    return res.status(400).json({ error: "请输入有效的探索主题" });
  }

  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    return res.status(500).json({
      error: "Gemini API key is not configured in Secrets. Please add GEMINI_API_KEY to Settings > Secrets."
    });
  }

  try {
    const ai = getGeminiClient();
    
    // Create prompt for custom learning roadmap
    const prompt = `You are "Compass", a cute, gamified AI learning roadmap companion.
Design a cohesive, step-by-step learning roadmap of 5 to 7 sequential nodes for the topic: "${topic}".

Requirements:
1. Generate the content in Chinese (or match the language of the user's topic).
2. The path should flow logically from introductory basics to advanced applications.
3. Every single node in the road map MUST have:
   - A descriptive "title" and brief "description".
   - A "card" explaining the concept with a highly engaging and funny "analogy" (生活类比) and 3 clear "keyPoints" (学习重点).
   - A "quiz" containing exactly 3 interactive multiple-choice questions (options A, B, C) testing the concept. Each question must include an "answer" ('A', 'B', or 'C') and a friendly "explanation" (解析) explaining why it is correct.
4. Keep the tone friendly, encouraging, and exciting, similar to Duolingo or a video game quest map!
5. Provide logical, alternating coordinates (x, y) for layout. For node i (0-indexed):
   - Set x alternating: 250 (for first node), then 100, then 400, then 250, then 100, then 400, etc.
   - Set y increasing by 120 per node: 100 for node 0, 220 for node 1, 340 for node 2, 460 for node 3, 580 for node 4, 700 for node 5, etc.

Return the result as a single course JSON object conforming to the requested schema.`;

    console.log(`Generating course for topic: "${topic}" using gemini-3.5-flash...`);

    const response = await ai.models.generateContent({
      model: "gemini-3.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { 
              type: Type.STRING, 
              description: "A URL-safe slug ID based on the topic, e.g. quantum-computing" 
            },
            title: { 
              type: Type.STRING, 
              description: "The name of the course topic, e.g. 量子计算" 
            },
            icon: { 
              type: Type.STRING, 
              description: "A single matching emoji icon for the course, e.g. 🌀" 
            },
            description: { 
              type: Type.STRING, 
              description: "A fun, inspiring overview of the course" 
            },
            nodes: {
              type: Type.ARRAY,
              description: "The ordered list of learning roadmap nodes",
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING, description: "A unique slug node ID" },
                  title: { type: Type.STRING, description: "The node name" },
                  description: { type: Type.STRING, description: "Brief description of this node's focus" },
                  x: { type: Type.NUMBER, description: "X coordinate of node" },
                  y: { type: Type.NUMBER, description: "Y coordinate of node" },
                  card: {
                    type: Type.OBJECT,
                    properties: {
                      concept: { type: Type.STRING, description: "Simple, precise explanation of the concept" },
                      analogy: { type: Type.STRING, description: "An engaging, humorous real-life analogy (生活类比)" },
                      keyPoints: {
                        type: Type.ARRAY,
                        items: { type: Type.STRING },
                        description: "3 core points to learn or check off"
                      }
                    },
                    required: ["concept", "analogy", "keyPoints"]
                  },
                  quiz: {
                    type: Type.ARRAY,
                    description: "Exactly 3 interactive quiz questions for this node",
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        question: { type: Type.STRING },
                        options: {
                          type: Type.ARRAY,
                          items: { type: Type.STRING },
                          description: "Three options starting with 'A ', 'B ', 'C '"
                        },
                        answer: { type: Type.STRING, description: "Must be 'A', 'B', or 'C' only" },
                        explanation: { type: Type.STRING, description: "Encouraging explanation of the correct option" }
                      },
                      required: ["question", "options", "answer", "explanation"]
                    }
                  }
                },
                required: ["id", "title", "description", "x", "y", "card", "quiz"]
              }
            }
          },
          required: ["id", "title", "icon", "description", "nodes"]
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("Empty response received from Gemini API");
    }

    const courseData = JSON.parse(text);
    return res.json({ success: true, course: courseData });

  } catch (error: any) {
    console.error("Gemini course generation error:", error);
    return res.status(500).json({ 
      error: error.message || "AI 路线生成失败，请稍后重试。" 
    });
  }
});

// Start server and handle Vite middleware
async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    // Dynamic import to prevent bundler errors
    const { createServer: createViteServer } = await import("vite");
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`LearnCompass server listening on http://0.0.0.0:${PORT}`);
  });
}

startServer().catch(err => {
  console.error("Failed to start server:", err);
});
